1	import {
2	  BadRequestException,
3	  HttpStatus,
4	  InternalServerErrorException,
5	  Logger,
6	  type RequestMethod,
7	  StreamableFile,
8	  VERSION_NEUTRAL,
9	  type VersioningOptions,
10	  VersioningType,
11	} from '@nestjs/common';
12	import cors from 'cors';
13	import express from 'express';
14	import type { Server } from 'http';
15	import * as http from 'http';
16	import * as https from 'https';
17	import { pathToRegexp } from 'path-to-regexp';
18	import { Duplex, Writable } from 'stream';
19	import {
20	  NestExpressBodyParserOptionsFor,
21	  NestExpressBodyParserType,
22	} from '../interfaces/nest-express-body-parser.interface.js';
23	import { ServeStaticOptions } from '../interfaces/serve-static-options.interface.js';
24	import { getBodyParserOptions } from './utils/get-body-parser-options.util.js';
25	import {
26	  type CorsOptions,
27	  type CorsOptionsDelegate,
28	  type VersionValue,
29	  addLeadingSlash,
30	  isFunction,
31	  isNil,
32	  isObject,
33	  isString,
34	  isUndefined,
35	  stripEndSlash,
36	} from '@nestjs/common/internal';
37	import type { NestApplicationOptions } from '@nestjs/common';
38	import { AbstractHttpAdapter } from '@nestjs/core';
39	import {
40	  RouterMethodFactory,
41	  LegacyRouteConverter,
42	} from '@nestjs/core/internal';
43	
44	type VersionedRoute = <
45	  TRequest extends Record<string, any> = any,
46	  TResponse = any,
47	>(
48	  req: TRequest,
49	  res: TResponse,
50	  next: () => void,
51	) => any;
52	
53	/**
54	 * @publicApi
55	 */
56	export class ExpressAdapter extends AbstractHttpAdapter<
57	  http.Server | https.Server
58	> {
59	  private readonly routerMethodFactory = new RouterMethodFactory();
60	  private readonly logger = new Logger(ExpressAdapter.name);
61	  private readonly openConnections = new Set<Duplex>();
62	  private readonly registeredPrefixes = new Set<string>();
63	  private isShuttingDown = false;
64	  private onRequestHook?: (
65	    req: express.Request,
66	    res: express.Response,
67	    done: () => void,
68	  ) => Promise<void> | void;
69	  private onResponseHook?: (
70	    req: express.Request,
71	    res: express.Response,
72	  ) => Promise<void> | void;
73	
74	  constructor(instance?: any) {
75	    super(instance || express());
76	    this.instance!.use((req, res, next) => {
77	      if (this.onResponseHook) {
78	        res.on('finish', () => {
79	          void this.onResponseHook!.apply(this, [req, res]);
80	        });
81	      }
82	
83	      if (this.onRequestHook) {
84	        void this.onRequestHook.apply(this, [req, res, next]);
85	      } else {
86	        next();
87	      }
88	    });
89	  }
90	
91	  public setOnRequestHook(
92	    onRequestHook: (
93	      req: express.Request,
94	      res: express.Response,
95	      done: () => void,
96	    ) => Promise<void> | void,
97	  ) {
98	    this.onRequestHook = onRequestHook;
99	  }
100	
101	  public setOnResponseHook(
102	    onResponseHook: (
103	      req: express.Request,
104	      res: express.Response,
105	    ) => Promise<void> | void,
106	  ) {
107	    this.onResponseHook = onResponseHook;
108	  }
109	
110	  public reply(response: any, body: any, statusCode?: number) {
111	    if (!isNil(statusCode)) {
112	      response.status(statusCode);
113	    }
114	    if (isNil(body)) {
115	      return response.send();
116	    }
117	    if (body instanceof StreamableFile) {
118	      this.applyStreamHeaders(response, body);
119	      const stream = body.getStream();
120	      stream.once('error', err => {
121	        body.errorHandler(err, response);
122	      });
123	      return stream
124	        .pipe<Writable>(response)
125	        .on('error', (err: Error) => body.errorLogger(err));
126	    }
127	    const responseContentType = response.getHeader('Content-Type');
128	    if (
129	      typeof responseContentType === 'string' &&
130	      !responseContentType.startsWith('application/json') &&
131	      body?.statusCode >= HttpStatus.BAD_REQUEST
132	    ) {
133	      this.logger.warn(
134	        "Content-Type doesn't match Reply body, you might need a custom ExceptionFilter for non-JSON responses",
135	      );
136	      response.setHeader('Content-Type', 'application/json');
137	    }
138	    return isObject(body) ? response.json(body) : response.send(String(body));
139	  }
140	
141	  public status(response: any, statusCode: number) {
142	    return response.status(statusCode);
143	  }
144	
145	  public end(response: any, message?: string) {
146	    return response.end(message);
147	  }
148	
149	  public render(response: any, view: string, options: any) {
150	    return response.render(view, options);
151	  }
152	
153	  public redirect(response: any, statusCode: number, url: string) {
154	    return response.redirect(statusCode, url);
155	  }
156	
157	  public setErrorHandler(handler: Function, prefix?: string) {
158	    const normalizedPrefix = this.normalizePrefix(prefix);
159	    if (normalizedPrefix) {
160	      const router = express.Router();
161	      router.use(handler as any);
162	      this.use(normalizedPrefix, router);
163	    }
164	    // Always mount the error handler at the root as well, so routes living
165	    // outside the global prefix (e.g. "setGlobalPrefix" exclusions or
166	    // root-mounted routes) still pass through the exception layer.
167	    return this.use(handler);
168	  }
169	
170	  public setNotFoundHandler(handler: Function, prefix?: string) {
171	    const normalizedPrefix = this.normalizePrefix(prefix);
172	    if (normalizedPrefix) {
173	      this.registeredPrefixes.add(normalizedPrefix);
174	      const router = express.Router();
175	      router.all('*path', handler as any);
176	      return this.use(normalizedPrefix, router);
177	    }
178	    return this.use(
179	      (
180	        req: express.Request,
181	        res: express.Response,
182	        next: express.NextFunction,
183	      ) => {
184	        // When multiple apps share this adapter, a non-prefixed app's 404
185	        // handler may be registered before a prefixed app's routes. Skip
186	        // requests whose path belongs to another app's prefix so they can
187	        // reach the correct route handlers further in the stack.
188	        const path = req.originalUrl.split(/[?#]/)[0];
189	        for (const registeredPrefix of this.registeredPrefixes) {
190	          // Match on full path segments only, so a prefix of "/api" does not
191	          // swallow unrelated paths such as "/apiary".
192	          if (
193	            path === registeredPrefix ||
194	            path.startsWith(`${registeredPrefix}/`)
195	          ) {
196	            return next();
197	          }
198	        }
199	        return (handler as any)(req, res, next);
200	      },
201	    );
202	  }
203	
204	  public isHeadersSent(response: any): boolean {
205	    return response.headersSent;
206	  }
207	
208	  public getHeader(response: any, name: string) {
209	    return response.get(name);
210	  }
211	
212	  public setHeader(response: any, name: string, value: string) {
213	    return response.set(name, value);
214	  }
215	
216	  public appendHeader(response: any, name: string, value: string) {
217	    return response.append(name, value);
218	  }
219	
220	  public normalizePath(path: string): string {
221	    try {
222	      const convertedPath = LegacyRouteConverter.tryConvert(path);
223	      // Call "pathToRegexp" to trigger a TypeError if the path is invalid
224	      pathToRegexp(convertedPath);
225	      return convertedPath;
226	    } catch (e) {
227	      if (e instanceof TypeError) {
228	        LegacyRouteConverter.printError(path);
229	      }
230	      throw e;
231	    }
232	  }
233	
234	  public listen(port: string | number, callback?: () => void): Server;
235	  public listen(
236	    port: string | number,
237	    hostname: string,
238	    callback?: () => void,
239	  ): Server;
240	  public listen(port: any, ...args: any[]): Server {
241	    return this.httpServer.listen(port, ...args);
242	  }
243	
244	  public beforeClose() {
245	    this.isShuttingDown = true;
246	  }
247	
248	  public close() {
249	    this.isShuttingDown = true;
250	    this.closeOpenConnections();
251	
252	    if (!this.httpServer) {
253	      return undefined;
254	    }
255	    return new Promise(resolve => this.httpServer.close(resolve));
256	  }
257	
258	  public set(...args: any[]) {
259	    return this.instance.set(...args);
260	  }
261	
262	  public enable(...args: any[]) {
263	    return this.instance.enable(...args);
264	  }
265	
266	  public disable(...args: any[]) {
267	    return this.instance.disable(...args);
268	  }
269	
270	  public engine(...args: any[]) {
271	    return this.instance.engine(...args);
272	  }
273	
274	  public useStaticAssets(path: string, options: ServeStaticOptions) {
275	    if (options && options.prefix) {
276	      return this.use(options.prefix, express.static(path, options));
277	    }
278	    return this.use(express.static(path, options));
279	  }
280	
281	  public setBaseViewsDir(path: string | string[]) {
282	    return this.set('views', path);
283	  }
284	
285	  public setViewEngine(engine: string) {
286	    return this.set('view engine', engine);
287	  }
288	
289	  public getRequestHostname(request: any): string {
290	    return request.hostname;
291	  }
292	
293	  public getRequestMethod(request: any): string {
294	    return request.method;
295	  }
296	
297	  public getRequestUrl(request: any): string {
298	    return request.originalUrl;
299	  }
300	
301	  public enableCors(options: CorsOptions | CorsOptionsDelegate<any>) {
302	    return this.use(cors(options as any));
303	  }
304	
305	  public createMiddlewareFactory(
306	    requestMethod: RequestMethod,
307	  ): (path: string, callback: Function) => any {
308	    return (path: string, callback: Function) => {
309	      try {
310	        const convertedPath = LegacyRouteConverter.tryConvert(path);
311	        return this.routerMethodFactory
312	          .get(this.instance, requestMethod)
313	          .call(this.instance, convertedPath, callback);
314	      } catch (e) {
315	        if (e instanceof TypeError) {
316	          LegacyRouteConverter.printError(path);
317	        }
318	        throw e;
319	      }
320	    };
321	  }
322	
323	  public initHttpServer(options: NestApplicationOptions) {
324	    const isHttpsEnabled = options && options.httpsOptions;
325	    if (isHttpsEnabled) {
326	      this.httpServer = https.createServer(
327	        options.httpsOptions!,
328	        this.getInstance(),
329	      );
330	    } else {
331	      this.httpServer = http.createServer(this.getInstance());
332	    }
333	
334	    if (options?.return503OnClosing) {
335	      this.instance.use((req: any, res: any, next: any) => {
336	        if (this.isShuttingDown) {
337	          res.set('Connection', 'close');
338	          res.status(503).send('Service Unavailable');
339	        } else {
340	          next();
341	        }
342	      });
343	    }
344	
345	    if (options?.forceCloseConnections) {
346	      this.trackOpenConnections();
347	    }
348	  }
349	
350	  public registerParserMiddleware(prefix?: string, rawBody?: boolean) {
351	    const bodyParserJsonOptions = getBodyParserOptions('json', rawBody!);
352	    const bodyParserUrlencodedOptions = getBodyParserOptions(
353	      'urlencoded',
354	      rawBody!,
355	      { extended: true },
356	    );
357	
358	    const parserMiddleware = {
359	      jsonParser: express.json(bodyParserJsonOptions),
360	      urlencodedParser: express.urlencoded(bodyParserUrlencodedOptions),
361	    };
362	    Object.keys(parserMiddleware)
363	      .filter(parser => !this.isMiddlewareApplied(parser))
364	      .forEach(parserKey => this.use(parserMiddleware[parserKey]));
365	  }
366	
367	  public useBodyParser<ParserType extends NestExpressBodyParserType>(
368	    type: ParserType,
369	    rawBody: boolean,
370	    options?: NestExpressBodyParserOptionsFor<ParserType>,
371	  ): this {
372	    const parserOptions = getBodyParserOptions(type, rawBody, options);
373	    const parser = express[type](parserOptions);
374	
375	    this.use(parser);
376	
377	    return this;
378	  }
379	
380	  public setLocal(key: string, value: any) {
381	    this.instance.locals[key] = value;
382	    return this;
383	  }
384	
385	  public getType(): string {
386	    return 'express';
387	  }
388	
389	  public isRouteOrderSensitive(): boolean {
390	    return true;
391	  }
392	
393	  public applyVersionFilter(
394	    handler: Function,
395	    version: VersionValue,
396	    versioningOptions: VersioningOptions,
397	  ): VersionedRoute {
398	    const callNextHandler: VersionedRoute = (req, res, next) => {
399	      if (!next) {
400	        throw new InternalServerErrorException(
401	          'HTTP adapter does not support filtering on version',
402	        );
403	      }
404	      return next();
405	    };
406	
407	    if (
408	      version === VERSION_NEUTRAL ||
409	      // URL Versioning is done via the path, so the filter continues forward
410	      versioningOptions.type === VersioningType.URI
411	    ) {
412	      const handlerForNoVersioning: VersionedRoute = (req, res, next) =>
413	        handler(req, res, next);
414	
415	      return handlerForNoVersioning;
416	    }
417	
418	    // Custom Extractor Versioning Handler
419	    if (versioningOptions.type === VersioningType.CUSTOM) {
420	      const handlerForCustomVersioning: VersionedRoute = (req, res, next) => {
421	        const extractedVersion = versioningOptions.extractor(req);
422	
423	        if (Array.isArray(version)) {
424	          if (
425	            Array.isArray(extractedVersion) &&
426	            version.filter(v => extractedVersion.includes(v as string)).length
427	          ) {
428	            return handler(req, res, next);
429	          }
430	
431	          if (
432	            isString(extractedVersion) &&
433	            version.includes(extractedVersion)
434	          ) {
435	            return handler(req, res, next);
436	          }
437	        } else if (isString(version)) {
438	          // Known bug here - if there are multiple versions supported across separate
439	          // handlers/controllers, we can't select the highest matching handler.
440	          // Since this code is evaluated per-handler, then we can't see if the highest
441	          // specified version exists in a different handler.
442	          if (
443	            Array.isArray(extractedVersion) &&
444	            extractedVersion.includes(version)
445	          ) {
446	            return handler(req, res, next);
447	          }
448	
449	          if (isString(extractedVersion) && version === extractedVersion) {
450	            return handler(req, res, next);
451	          }
452	        }
453	
454	        return callNextHandler(req, res, next);
455	      };
456	
457	      return handlerForCustomVersioning;
458	    }
459	
460	    // Media Type (Accept Header) Versioning Handler
461	    if (versioningOptions.type === VersioningType.MEDIA_TYPE) {
462	      const handlerForMediaTypeVersioning: VersionedRoute = (
463	        req,
464	        res,
465	        next,
466	      ) => {
467	        const MEDIA_TYPE_HEADER = 'Accept';
468	        const acceptHeaderValue: string | undefined =
469	          req.headers?.[MEDIA_TYPE_HEADER] ||
470	          req.headers?.[MEDIA_TYPE_HEADER.toLowerCase()];
471	
472	        const acceptHeaderVersionParameter = acceptHeaderValue
473	          ? acceptHeaderValue.split(';')[1]
474	          : undefined;
475	
476	        // No version was supplied
477	        if (isUndefined(acceptHeaderVersionParameter)) {
478	          if (Array.isArray(version)) {
479	            if (version.includes(VERSION_NEUTRAL)) {
480	              return handler(req, res, next);
481	            }
482	          }
483	        } else {
484	          const headerVersion = acceptHeaderVersionParameter.split(
485	            versioningOptions.key,
486	          )[1];
487	
488	          if (Array.isArray(version)) {
489	            if (version.includes(headerVersion)) {
490	              return handler(req, res, next);
491	            }
492	          } else if (isString(version)) {
493	            if (version === headerVersion) {
494	              return handler(req, res, next);
495	            }
496	          }
497	        }
498	
499	        return callNextHandler(req, res, next);
500	      };
501	
502	      return handlerForMediaTypeVersioning;
503	    }
504	
505	    // Header Versioning Handler
506	    if (versioningOptions.type === VersioningType.HEADER) {
507	      const handlerForHeaderVersioning: VersionedRoute = (req, res, next) => {
508	        const customHeaderVersionParameter: string | undefined =
509	          req.headers?.[versioningOptions.header] ||
510	          req.headers?.[versioningOptions.header.toLowerCase()];
511	
512	        // No version was supplied
513	        if (isUndefined(customHeaderVersionParameter)) {
514	          if (Array.isArray(version)) {
515	            if (version.includes(VERSION_NEUTRAL)) {
516	              return handler(req, res, next);
517	            }
518	          }
519	        } else {
520	          if (Array.isArray(version)) {
521	            if (version.includes(customHeaderVersionParameter)) {
522	              return handler(req, res, next);
523	            }
524	          } else if (isString(version)) {
525	            if (version === customHeaderVersionParameter) {
526	              return handler(req, res, next);
527	            }
528	          }
529	        }
530	
531	        return callNextHandler(req, res, next);
532	      };
533	
534	      return handlerForHeaderVersioning;
535	    }
536	
537	    throw new Error('Unsupported versioning options');
538	  }
539	
540	  public mapException(error: unknown): unknown {
541	    switch (true) {
542	      // SyntaxError is thrown by Express body-parser when given invalid JSON (#422, #430)
543	      // URIError is thrown by Express when given a path parameter with an invalid percentage
544	      // encoding, e.g. '%FF' (#8915)
545	      case error instanceof SyntaxError || error instanceof URIError:
546	        return new BadRequestException(error.message);
547	      default:
548	        return error;
549	    }
550	  }
551	
552	  private normalizePrefix(prefix?: string): string {
553	    return stripEndSlash(addLeadingSlash(prefix));
554	  }
555	
556	  private trackOpenConnections() {
557	    this.httpServer.on('connection', (socket: Duplex) => {
558	      this.openConnections.add(socket);
559	
560	      socket.on('close', () => this.openConnections.delete(socket));
561	    });
562	  }
563	
564	  private closeOpenConnections() {
565	    for (const socket of this.openConnections) {
566	      socket.destroy();
567	      this.openConnections.delete(socket);
568	    }
569	  }
570	
571	  private isMiddlewareApplied(name: string): boolean {
572	    const app = this.getInstance();
573	    return (
574	      !!app.router &&
575	      !!app.router.stack &&
576	      isFunction(app.router.stack.filter) &&
577	      app.router.stack.some(
578	        (layer: any) => layer && layer.handle && layer.handle.name === name,
579	      )
580	    );
581	  }
582	
583	  private setHeaderIfNotExists(
584	    response: any,
585	    name: string,
586	    value?: string | string[] | number,
587	  ) {
588	    if (value !== undefined && response.getHeader(name) === undefined) {
589	      const headerValue = Array.isArray(value) ? value.join(',') : value;
590	      response.setHeader(name, headerValue);
591	    }
592	  }
593	
594	  private applyStreamHeaders(response: any, streamable: StreamableFile) {
595	    const headers = streamable.getHeaders();
596	
597	    this.setHeaderIfNotExists(response, 'Content-Type', headers.type);
598	    this.setHeaderIfNotExists(
599	      response,
600	      'Content-Disposition',
601	      headers.disposition,
602	    );
603	    this.setHeaderIfNotExists(response, 'Content-Length', headers.length);
604	  }
605	}
